#include <stdio.h>

int main(void) {
    int unique[1000];
    int count = 0;
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        int seen = 0;
        for (int j = 0; j < count; j++) {
            if (unique[j] == x) {
                seen = 1;
                break;
            }
        }
        if (!seen) {
            unique[count] = x;
            count++;
        }
    }
    for (int i = 0; i < count; i++) {
        if (i > 0) {
            printf(" ");
        }
        printf("%d", unique[i]);
    }
    printf("\n");
    return 0;
}

